insert into public.question_keys (question_id, answer, explanation, wrong, mistakes) values
  ('ug-prog-001', '"a"'::jsonb, '// is floor division: it divides and rounds down to a whole number. 7 / 2 = 3.5, rounded down to 3.', '{"b":"3.5 is what 7 / 2 (true division) gives.","c":"Floor division rounds down, not to the nearest whole number.","d":"1 is the remainder, given by 7 % 2."}'::jsonb, null),
  ('ug-prog-002', '{"value":3,"tolerance":0}'::jsonb, 'The outer list has three elements: 1, the list [2, 3], and 4. len does not count inside the nested list.', null, '[{"value":4,"why":"The inner list [2, 3] counts as a single element of the outer list."}]'::jsonb),
  ('ug-prog-003', '"a"'::jsonb, 'Each step halves the remaining range, so at most about log₂ n steps are needed.', '{"b":"O(n) is linear search, checking items one by one.","c":"O(n log n) is typical of efficient sorting, not searching.","d":"O(1) would mean finding any item in one step regardless of n."}'::jsonb, null),
  ('ug-prog-004', '["a","c","e"]'::jsonb, 'Tuples, strings and integers cannot be changed after creation; operations on them create new objects.', '{"b":"Lists are mutable: append, remove and item assignment change them in place.","d":"Dictionaries are mutable: you can add, change and delete keys."}'::jsonb, null),
  ('ug-prog-005', '["c","d","a","b"]'::jsonb, 'Constant O(1) does not grow; O(log n) grows very slowly; O(n) grows in step with n; O(n²) grows fastest.', null, null),
  ('ug-prog-006', '"true"'::jsonb, 'Python uses zero-based indexing: for x = [''a'', ''b''], x[0] is ''a''.', '{"false":"Python, like C and Java, counts from 0. x[1] is the second element."}'::jsonb, null),
  ('ug-prog-007', '{"value":3,"tolerance":0}'::jsonb, 'x.sort() sorts in place to [1, 2, 3]. Index −1 is the last element: 3.', null, '[{"value":2,"why":"2 was last before sorting; sort() changes the list in place."},{"value":1,"why":"−1 means the last element, not the first."}]'::jsonb),
  ('ug-prog-008', '{"accept":["recursive","recursive function","recursion","a recursive function"]}'::jsonb, 'A recursive function calls itself on a smaller version of the problem, and needs a base case so that it stops.', null, null),
  ('ug-prog-009', '{"a":"z","b":"x","c":"y"}'::jsonb, 'A stack is like a pile of plates (LIFO); a queue is like a line at a shop (FIFO); a hash table maps keys to values for fast lookup.', null, null),
  ('ug-prog-010', '"a"'::jsonb, 'A commit saves a snapshot of the staged changes, with a message, in your local history.', '{"b":"Uploading is git push.","c":"Downloading is git fetch or git pull.","d":"Creating a branch is git branch or git switch -c."}'::jsonb, null),
  ('ug-cs-001', '{"value":1024,"tolerance":0}'::jsonb, 'Each bit doubles the number of combinations: 2¹⁰ = 1024.', null, '[{"value":20,"why":"20 is 2 × 10; the combinations multiply: 2 × 2 × … (ten times)."},{"value":1023,"why":"1023 is the largest unsigned value; counting 0 as well gives 1024 values."}]'::jsonb),
  ('ug-cs-002', '"a"'::jsonb, 'HTTP is an application-layer protocol used by web browsers and servers. It runs on top of TCP (transport) and IP (internet).', '{"b":"The transport layer holds TCP and UDP.","c":"The internet layer holds IP.","d":"The link layer covers physical networks such as Ethernet and Wi-Fi."}'::jsonb, null),
  ('ug-cs-003', '"b"'::jsonb, 'Each of the four parts of an IPv4 address is one byte, so it must be from 0 to 255. 256 is too big.', '{"a":"192.168.0.1 is valid (a common private home-network address).","c":"10.0.0.255 is valid: every part is between 0 and 255.","d":"8.8.8.8 is valid (a well-known public DNS server)."}'::jsonb, null),
  ('ug-cs-004', '"false"'::jsonb, 'Hashing is one-way: there is no key and no decryption. That is why systems store password hashes rather than passwords.', '{"true":"Hashing is not encryption. It is designed so that the input cannot be worked out from the hash, other than by guessing."}'::jsonb, null),
  ('ug-cs-005', '{"value":255,"tolerance":0}'::jsonb, 'F = 15. FF = 15 × 16 + 15 = 240 + 15 = 255, the largest value of one byte.', null, '[{"value":30,"why":"30 adds the digits; the left F is worth 15 × 16."},{"value":256,"why":"256 is 16²; FF is one less."}]'::jsonb),
  ('ug-cs-006', '["a","b"]'::jsonb, 'AND gives 1 only when both inputs are 1. OR gives 1 when at least one is 1.', '{"c":"NAND is NOT-AND: with both inputs 1 it outputs 0.","d":"XOR outputs 1 only when the inputs differ.","e":"NOR outputs 1 only when both inputs are 0."}'::jsonb, null),
  ('ug-cs-007', '["b","d","a","c"]'::jsonb, 'Registers sit inside the CPU core, cache is on the chip, RAM is on the motherboard and an SSD is external storage. Faster memory is smaller and more expensive.', null, null),
  ('ug-cs-008', '{"value":8,"tolerance":0}'::jsonb, 'A byte is 8 bits, enough for 256 different values (0–255).', null, '[{"value":4,"why":"4 bits is a nibble, half a byte."}]'::jsonb),
  ('ug-stat-001', '{"value":0.7,"tolerance":0.001}'::jsonb, 'Mutually exclusive events cannot happen together, so P(A or B) = P(A) + P(B) = 0.7.', null, '[{"value":0.12,"why":"0.12 is P(A) × P(B), which would be P(A and B) for independent events, not P(A or B)."},{"value":0.58,"why":"There is no overlap to subtract: P(A and B) = 0 for mutually exclusive events."}]'::jsonb),
  ('ug-stat-002', '{"value":3.5,"tolerance":0.001}'::jsonb, 'E[X] = (1 + 2 + 3 + 4 + 5 + 6) ÷ 6 = 21 ÷ 6 = 3.5. It need not be a possible outcome.', null, '[{"value":3,"why":"The expected value is the mean, 3.5; it does not have to be a whole number."}]'::jsonb),
  ('ug-stat-003', '"a"'::jsonb, 'The empirical (68–95–99.7) rule: about 68% within 1 SD, 95% within 2 SD and 99.7% within 3 SD.', '{"b":"95% is within two standard deviations.","c":"99.7% is within three standard deviations.","d":"50% of values lie on each side of the mean, not within one SD."}'::jsonb, null),
  ('ug-stat-004', '{"value":0.375,"tolerance":0.001}'::jsonb, 'There are 8 equally likely outcomes, and 3 have exactly two heads (HHT, HTH, THH). 3/8 = 0.375.', null, '[{"value":0.25,"why":"0.25 is (1/2)², ignoring the third toss and the 3 orders."},{"value":0.125,"why":"1/8 is one particular order; there are 3 orders with two heads."}]'::jsonb),
  ('ug-stat-005', '"false"'::jsonb, 'Correlation shows variables move together, not why. A third factor may drive both (ice-cream sales and drownings both rise in hot weather), or it may be chance.', '{"true":"Correlation alone cannot establish causation; that needs controlled experiments or careful causal reasoning."}'::jsonb, null),
  ('ug-stat-006', '"a"'::jsonb, 'Since p < 0.05, results this extreme would be unlikely if the null hypothesis were true, so we reject it at the 5% level.', '{"b":"A p-value is the probability of the data (or more extreme) given the null, not the probability that the null is true.","c":"p-values do not give the probability that a hypothesis is true.","d":"Significance is not size: a tiny effect can be significant with a large sample."}'::jsonb, null),
  ('ug-stat-007', '{"value":12,"tolerance":0}'::jsonb, 'Var(aX) = a² Var(X) = 4 × 3 = 12.', null, '[{"value":6,"why":"Variance scales by the square of the constant: 2² = 4, not 2."}]'::jsonb),
  ('ug-stat-008', '["a","c","d"]'::jsonb, 'Range, standard deviation and interquartile range describe how spread out data are.', '{"b":"The mean is a measure of centre.","e":"The mode is a measure of centre (the most common value)."}'::jsonb, null),
  ('ug-stat-009', '{"a":"y","b":"z","c":"x"}'::jsonb, 'Eye colour has categories with no order (nominal). Sizes have a natural order (ordinal). Height can take any value in a range (continuous).', null, null),
  ('ug-stat-010', '{"value":6,"tolerance":0}'::jsonb, 'Sort the data: 1, 3, 5, 7, 9, 11. With an even count, the median is the mean of the middle two: (5 + 7) ÷ 2 = 6.', null, '[{"value":1,"why":"Sort the data before finding the middle."},{"value":7,"why":"With six values, average the two middle ones (5 and 7)."}]'::jsonb),
  ('ug-calc-001', '{"value":1,"tolerance":0}'::jsonb, 'f′(x) = 3x² − 2, so f′(1) = 3 − 2 = 1.', null, '[{"value":-1,"why":"−1 is f(1) = 1 − 2; differentiate first, then substitute."}]'::jsonb),
  ('ug-calc-002', '"a"'::jsonb, 'd/dx (ln x) = 1/x.', '{"b":"Only eˣ is its own derivative, not ln x.","c":"eˣ is the derivative of eˣ, the inverse function of ln x.","d":"x ln x − x is the integral of ln x."}'::jsonb, null),
  ('ug-calc-003', '{"value":2,"tolerance":0.001}'::jsonb, '∫ sin x dx = −cos x. From 0 to π: (−cos π) − (−cos 0) = 1 + 1 = 2.', null, '[{"value":0,"why":"0 is the integral from 0 to 2π, where positive and negative areas cancel."}]'::jsonb),
  ('ug-calc-004', '"a"'::jsonb, 'Product rule: (uv)′ = u′v + uv′ = 1·eˣ + x·eˣ = eˣ(x + 1).', '{"b":"That multiplies the derivatives (1 × eˣ); the product rule adds two terms.","c":"That forgets the u′v term.","d":"The second term should be x·eˣ, not x."}'::jsonb, null),
  ('ug-calc-005', '{"value":1,"tolerance":0}'::jsonb, 'For small x (in radians), sin x ≈ x, so (sin x)/x → 1. It can be shown with the squeeze theorem.', null, '[{"value":0,"why":"Both top and bottom go to 0, but their ratio approaches 1."}]'::jsonb),
  ('ug-calc-006', '"false"'::jsonb, 'f(x) = x³ has f′(0) = 0, but x = 0 is a point of inflection, not a maximum or minimum.', '{"true":"A zero derivative only means a stationary point. Check the sign change of f′ (or f″) to classify it: x³ at 0 is a counter-example."}'::jsonb, null),
  ('ug-calc-007', '{"value":3,"tolerance":0}'::jsonb, 'dy/dx = 2x − 6 = 0 gives x = 3 (a minimum, since the x² coefficient is positive).', null, '[{"value":6,"why":"Solve 2x − 6 = 0: x = 3, not 6."},{"value":-4,"why":"−4 is the y-value at the stationary point; the question asks for x."}]'::jsonb),
  ('ug-calc-008', '"a"'::jsonb, 'd/dx ln|x| = 1/x, so ∫ 1/x dx = ln|x| + c. The power rule cannot be used here because n = −1.', '{"b":"The power rule fails for n = −1: it would divide by zero.","c":"−1/x² is the derivative of 1/x, not its integral.","d":"Differentiating 1/x² gives −2/x³, not 1/x."}'::jsonb, null),
  ('ug-psy-001', '"a"'::jsonb, 'The bell was neutral at first. After being paired with food, it triggers salivation by itself, making it a conditioned (learned) stimulus.', '{"b":"The food is the unconditioned stimulus: it causes salivation without learning.","c":"Salivating to food is the unconditioned response.","d":"Salivating to the bell is the conditioned response; the bell itself is a stimulus."}'::jsonb, null),
  ('ug-psy-002', '["b","d","e","a","c"]'::jsonb, 'Physiological (food, sleep) → safety → love and belonging → esteem → self-actualisation.', null, null),
  ('ug-psy-003', '"a"'::jsonb, 'The formal operational stage (from about age 11–12) brings abstract and hypothetical thinking.', '{"b":"In the concrete operational stage, logic works on concrete, real objects.","c":"The preoperational stage features symbolic play and egocentrism.","d":"The sensorimotor stage (birth to about 2) is about learning through senses and movement."}'::jsonb, null),
  ('ug-psy-004', '"false"'::jsonb, 'Short-term memory has a small capacity: classic estimates are about 7 ± 2 items (newer research suggests nearer 4 chunks), held for under a minute without rehearsal.', '{"true":"Long-term memory has a very large capacity, but short-term memory is strictly limited."}'::jsonb, null),
  ('ug-psy-005', '{"a":"y","b":"z","c":"x"}'::jsonb, 'Experiments manipulate an independent variable; case studies go deep on one case; surveys collect self-reports from many people.', null, null),
  ('ug-psy-006', '["a","b","d"]'::jsonb, 'The Big Five are openness, conscientiousness, extraversion, agreeableness and neuroticism (OCEAN).', '{"c":"Intelligence is a cognitive ability, measured separately from the Big Five.","e":"Happiness is a mood or well-being measure, not one of the five traits."}'::jsonb, null),
  ('ug-psy-007', '{"accept":["confirmation bias"]}'::jsonb, 'Confirmation bias leads people to notice, seek and remember evidence that fits their existing beliefs, and to discount evidence against them.', null, null),
  ('ug-acc-001', '"a"'::jsonb, 'Everything a business owns (assets) is financed either by what it owes (liabilities) or by the owners (equity).', '{"b":"Equity is added, not subtracted: both liabilities and equity finance the assets.","c":"Revenue and expenses belong in the income statement, not this equation.","d":"Equity = Assets − Liabilities."}'::jsonb, null),
  ('ug-acc-002', '{"value":30000,"tolerance":0,"unit":"RM"}'::jsonb, 'Equity = Assets − Liabilities = 50,000 − 20,000 = RM30,000.', null, '[{"value":70000,"why":"Equity is what is left after liabilities: subtract, do not add."}]'::jsonb),
  ('ug-acc-003', '"a"'::jsonb, 'It is money owed (a liability) and is due after more than 12 months, so it is non-current.', '{"b":"The loan is owed by the business, so it is a liability, not an asset.","c":"Equity is the owners'' stake; a loan is owed to an outside lender.","d":"Only the interest on the loan is an expense; the loan itself is a liability."}'::jsonb, null),
  ('ug-acc-004', '"true"'::jsonb, 'Each transaction affects at least two accounts with equal debits and credits, which keeps the accounting equation in balance.', '{"false":"That is the core rule of double entry: total debits always equal total credits."}'::jsonb, null),
  ('ug-acc-005', '{"value":2000,"tolerance":0,"unit":"RM"}'::jsonb, 'Depreciation = (cost − residual value) ÷ useful life = (10,000 − 2,000) ÷ 4 = RM2,000 per year.', null, '[{"value":2500,"why":"Subtract the residual value first: (10,000 − 2,000) ÷ 4."}]'::jsonb),
  ('ug-acc-006', '["a","b","d"]'::jsonb, 'Current assets are expected to be turned into cash or used within 12 months: inventory, receivables and cash.', '{"c":"Machinery is used for many years: a non-current asset.","e":"Buildings are long-term: a non-current asset."}'::jsonb, null),
  ('ug-acc-007', '{"value":30000,"tolerance":0,"unit":"RM"}'::jsonb, 'Gross profit = sales − cost of sales = 80,000 − 50,000 = RM30,000.', null, '[{"value":130000,"why":"Gross profit subtracts the cost of sales from sales."}]'::jsonb)
